cat >> crates/athena-cli/tests/drain.rs <<'EOF'

// ---------------------------------------------------------------------------------------------------------
// Proposals and approved jobs, against the real records

const IN_LIMIT: &str = "20261015-100000-aaaa";
const ABOVE_LIMIT: &str = "20261015-100001-bbbb";
const UNKNOWN_ROLE: &str = "20261015-100002-cccc";

fn proposal(id: &str, role: &str, rung: Ladder) -> athena_data::records::AnyRecord {
    athena_data::records::AnyRecord::WorkItem(Box::new(athena_data::records::WorkItem {
        id: athena_data::RecordId::parse(id).unwrap(),
        at: "2026-10-15T00:39:03Z".parse().unwrap(),
        role: role.into(),
        kind: WorkItemKind::Proposal,
        key: format!("proposal:{id}"),
        title: format!("Proposal {id}"),
        rung,
        source: Reference::path("src/lib.rs"),
        evidence: Vec::new(),
    }))
}

/// Seeds the audience role and three open proposals: one its role may change itself, one above that role's
/// limit, and one from a role that has no definition.
fn seed_proposals(fx: &Fixture) {
    let records = [
        athena_data::records::AnyRecord::Role(Box::new(athena_data::roles::audience(
            "2026-10-14T00:00:00Z".parse().unwrap(),
        ))),
        proposal(IN_LIMIT, "audience", Ladder::Implementation),
        proposal(ABOVE_LIMIT, "audience", Ladder::DesignDecisions),
        proposal(UNKNOWN_ROLE, "ghost", Ladder::Implementation),
    ];
    for record in &records {
        write(fx.root(), &[(&record.canonical_path(), &record.to_json())]);
    }
    fx.git.run(["add", "-A"]).unwrap();
    fx.git.run(["commit", "-q", "-m", "Seed proposals"]).unwrap();
}

fn rated_scenario() -> Scenario {
    let mut scenario = Scenario::default();
    scenario.audience = json!({
        "rating": 4,
        "findings": [{ "text": "Clear.", "source": "heading: Start here" }]
    });
    scenario
}

#[test]
fn drain_approves_an_in_limit_proposal_and_leaves_the_rest_waiting_for_a_person() {
    let fx = Fixture::new();
    seed_proposals(&fx);
    let athena = fx.athena(rated_scenario().script());
    let lander = RecordingLander::default();
    let steps = RealSteps {
        athena: &athena,
        ui: &Quiet,
        page: &StubPage,
        lander: &lander,
    };
    let queue = steps.queue().unwrap();
    let ids = |list: &[Waiting]| list.iter().map(|w| w.id.clone()).collect::<Vec<_>>();
    assert_eq!(ids(&queue.approvable), [IN_LIMIT]);
    assert_eq!(ids(&queue.waiting), [ABOVE_LIMIT, UNKNOWN_ROLE]);

    let report = drain::drain(&steps, limits(50.0), &Quiet).unwrap();
    assert_eq!(report.stop, Stop::TargetMet, "{}", display::drain(&report));
    assert_eq!(report.landed, 1);
    let records = Records::load(&fx.git, &fx.head()).unwrap();
    let [decision] = records.work_decisions.as_slice() else {
        panic!("one decision: {:?}", records.work_decisions)
    };
    assert_eq!(decision.work_item.as_str(), IN_LIMIT);
    let athena_data::records::WorkDecisionState::Approved { job } = &decision.decision else {
        panic!("approved")
    };
    assert_eq!(
        *lander.0.lock().unwrap(),
        [(job.as_str().to_string(), 0)],
        "the approved job was landed, before any rating"
    );
    assert_eq!(ids(&report.waiting), [ABOVE_LIMIT, UNKNOWN_ROLE]);
    assert!(report.queued.is_empty());
    let text = display::drain(&report);
    assert!(text.contains("needs a person"), "{text}");
    assert!(!text.contains(&format!("waiting     {IN_LIMIT}")), "{text}");
    // The proposals that wait were not decided.
    assert!(
        records
            .work_decisions
            .iter()
            .all(|d| d.work_item.as_str() == IN_LIMIT)
    );
}

#[test]
fn drain_works_a_job_a_work_decision_approved_once_and_not_again_when_closed() {
    let fx = Fixture::new();
    seed_proposals(&fx);
    let athena = fx.athena(rated_scenario().script());
    // A person approved the proposal earlier: the job is read, not run.
    let reading = athena.approve_work(ABOVE_LIMIT, &Quiet).unwrap();
    let job = reading.job.as_str().to_string();
    let lander = RecordingLander::default();
    let steps = RealSteps {
        athena: &athena,
        ui: &Quiet,
        page: &StubPage,
        lander: &lander,
    };
    let queue = steps.queue().unwrap();
    assert_eq!(
        queue.items.iter().map(|i| (i.job.as_str(), i.read)).collect::<Vec<_>>(),
        [(job.as_str(), true)],
        "the approved job is in the queue though its channel is not the steward's"
    );

    let report = drain::drain(&steps, Limits { max_jobs: 1, ..limits(50.0) }, &Quiet).unwrap();
    assert_eq!(report.landed, 1, "{}", display::drain(&report));
    assert_eq!(report.jobs.len(), 1);
    assert_eq!(report.jobs[0].job, job);
    assert_eq!(*lander.0.lock().unwrap(), [(job.clone(), 0)]);

    // The job is closed now; a second drain does not pick it up again.
    let again = steps.queue().unwrap();
    assert!(again.items.is_empty(), "{:?}", again.items);
}
